import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env_mapping=os.environ):
    config = defaults.copy()

    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(toml_config)
        except FileNotFoundError:
            pass

    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            config_value = _coerce_value(value, defaults.get(env_key))
            config[env_key] = config_value

    return config

def _coerce_value(value, default):
    if default is None:
        raise ConfigError(f'No default for {value}')

    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        return value.lower() in ['true', '1', 'yes']
    elif isinstance(default, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for {value}')

import pytest
import envcfg
import os
import tomllib

def test_load_config_defaults():
    defaults = {'key': 'value'}
    config = envcfg.load_config(defaults)
    assert config == {'key': 'value'}

def test_load_config_toml():
    toml_content = b'key = "toml_value"'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    defaults = {'key': 'default_value'}
    config = envcfg.load_config(defaults, toml_path='config.toml')
    assert config == {'key': 'toml_value'}
    os.remove('config.toml')

def test_load_config_env():
    os.environ['APP__KEY'] = 'env_value'
    defaults = {'key': 'default_value'}
    config = envcfg.load_config(defaults, env_prefix='APP__')
    assert config == {'key': 'env_value'}
    del os.environ['APP__KEY']

def test_load_config_precedence():
    toml_content = b'key = "toml_value"'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    os.environ['APP__KEY'] = 'env_value'
    defaults = {'key': 'default_value'}
    config = envcfg.load_config(defaults, toml_path='config.toml', env_prefix='APP__')
    assert config == {'key': 'env_value'}
    os.remove('config.toml')
    del os.environ['APP__KEY']

def test_load_config_coercion():
    os.environ['APP__KEY'] = '1'
    defaults = {'key': 0}
    config = envcfg.load_config(defaults, env_prefix='APP__')
    assert config == {'key': 1}
    del os.environ['APP__KEY']

def test_load_config_error_no_default():
    os.environ['APP__KEY'] = 'value'
    with pytest.raises(envcfg.ConfigError):
        envcfg.load_config({}, env_prefix='APP__')
    del os.environ['APP__KEY']

def test_load_config_error_unsupported_type():
    os.environ['APP__KEY'] = 'value'
    defaults = {'key': []}
    with pytest.raises(envcfg.ConfigError):
        envcfg.load_config(defaults, env_prefix='APP__')
    del os.environ['APP__KEY']
